            content = f.read().strip()
            if not content:
                print(f"{' ':20} | {path[-60:]} | 0     | 0     | Empty file")
                continue
            data = json.loads(content)

        # Copilot tools are often in an object where keys are the tool names
        # or they are objects in a list. Let's inspect the data type.
        tool_names = []
        if isinstance(data, dict):
            # If it's a map of name -> tool definition
            # Check for common patterns
            if all(isinstance(v, dict) and ('name' in v or 'description' in v) for v in data.values()):
                 tool_names = list(data.keys())
            else:
                 # Check if it's a single tool or something else
                 name = data.get('name') or data.get('function', {}).get('name')
                 if name:
                     tool_names = [name]
                 else:
                     # Maybe it's a list under a key
                     for key in ['tools', 'available_tools', 'functions']:
                         if key in data and isinstance(data[key], list):
                             for t in data[key]:
                                 if isinstance(t, dict):
                                     n = t.get('name') or t.get('function', {}).get('name')
                                     if n: tool_names.append(n)
        elif isinstance(data, list):
            for t in data:
                if isinstance(t, dict):
                    name = t.get('name') or t.get('function', {}).get('name')
                    if name:
                        tool_names.append(name)
                elif isinstance(t, str):
                    tool_names.append(t)

        counts = Counter(tool_names)
        duplicates = [name for name, count in counts.items() if count > 1]
        dup_count = sum(count - 1 for count in counts.values() if count > 1)

        from datetime import datetime
        mtime_str = datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M:%S')
        short_path = path.replace(os.path.expanduser("~"), "~")
        if len(short_path) > 57:
            short_path = "..." + short_path[-57:]

        print(f"{mtime_str:<20} | {short_path:<60} | {len(tool_names):<5} | {dup_count:<5} | {', '.join(duplicates)}")

    except Exception as e:
        print(f"Error processing {path}: {e}")

