          const s = JSON.parse(readFileSync(eventsFile, 'utf8'));
          if (!s.sessions) s.sessions = {};
          s.sessions[agent] = newSessionId;
          const usage = event.usage as Record<string, number>;
          if (usage && s.usage) {
            s.usage.inputTokens = (s.usage.inputTokens || 0) + (usage.input_tokens || 0);
            s.usage.outputTokens = (s.usage.outputTokens || 0) + (usage.output_tokens || 0);
            s.usage.cacheReadTokens = (s.usage.cacheReadTokens || 0) + (usage.cache_read_input_tokens || 0);
            s.usage.cacheWriteTokens = (s.usage.cacheWriteTokens || 0) + (usage.cache_creation_input_tokens || 0);
          }
          const cost = event.total_cost_usd as number;
          if (cost && s.usage) s.usage.totalCostUsd = (s.usage.totalCostUsd || 0) + cost;
          writeFileSync(eventsFile, JSON.stringify(s, null, 2));
        } catch {}
      } else if (type === 'error') {
        const message = typeof event.message === 'string'
          ? event.message
          : JSON.stringify(event.message ?? event);
        if (message) {
          const rendered = `[provider-error] ${message}`;
          lastResultText = rendered;
          noteDiagnostic(rendered);
          try {
            const s = JSON.parse(readFileSync(eventsFile, 'utf8'));
            s.events.push({
              time: new Date().toISOString(),
              agent,
              phase: s.currentPhase || 'concept',
              type: 'failure',
              text: rendered,
            });
            writeFileSync(eventsFile, JSON.stringify(s, null, 2));
          } catch {}
        }
      }
    });

    child.stderr.on('data', (chunk) => {
      const text = chunk.toString();
      stderr += text;
      noteDiagnostic(text);
    });

    child.on('close', async () => {
      if (canFallbackToHost && isRecoverableDockerAuthFailure(`${diagnosticTail}\n${stderr}\n${lastResultText}`)) {
        try {
          const s = JSON.parse(readFileSync(eventsFile, 'utf8'));
          const phase = s.currentPhase || 'concept';
          s.events.push({
            time: new Date().toISOString(),
            agent: 'system',
            phase,
            type: 'status',
            text: `Isolated ${roleLabel(agent)} auth is unavailable. Retrying on the host.`,
          });
          s.events.push({
            time: new Date().toISOString(),
            agent: 'S',
            phase,
            type: 'text',
            text: `I could not keep the ${roleLabel(agent)} isolated for this turn because Claude subscription auth is unavailable in Docker right now, so I am retrying it on the host instead of failing the run.`,
          });
          writeFileSync(eventsFile, JSON.stringify(s, null, 2));
        } catch {}

        resolveResponse(await streamClaude(
          { ...opts, forceHost: true },
          eventsFile,
          agent,
          sessionId,
        ));
        return;
      }

      // Set agent back to idle
      try {
        const s = JSON.parse(readFileSync(eventsFile, 'utf8'));
        if (s.agentStatus) s.agentStatus[agent] = 'idle';
        writeFileSync(eventsFile, JSON.stringify(s, null, 2));
      } catch {}
      resolveResponse(NextResponse.json({ success: true, sessionId: newSessionId }));
    });
    child.on('error', (err) => {
      resolveResponse(NextResponse.json({ success: false, error: err instanceof Error ? err.message : String(err) }, { status: 500 }));
    });
  });
}

// ── Manual mode ─────────────────────────────────────────────────────

async function handleManual(agent: string, message: string, model: string, modelProvider?: string) {
  const eventsFile = join(MANUAL_DIR, 'manual-state.json');
  const state = getManualState();
  const sessions = (state.sessions as Record<string, string>) || {};
  const sessionId = sessions[agent] || '';

  // Set agent active
  const agentStatus = (state.agentStatus as Record<string, string>) || {};
  agentStatus[agent] = 'active';
  state.agentStatus = agentStatus;

  // Append event — detect handoffs vs regular user messages
  const events = (state.events as Array<Record<string, unknown>>) || [];
  const handoffMatch = message.match(/^\[HANDOFF:(\w)→(\w)\]\s/);
  if (handoffMatch) {
    const fromAgent = handoffMatch[1];
    const handoffText = message.replace(/^\[HANDOFF:\w→\w\]\s/, '').replace(/\n\nReview this and continue the work\.$/, '');
    events.push({ time: new Date().toISOString(), agent: fromAgent, phase: 'concept', type: 'handoff', text: `→ ${agent}: ${handoffText}` });
  } else {
    events.push({ time: new Date().toISOString(), agent, phase: 'concept', type: 'user_msg', text: `You: ${message}` });
  }
  state.events = events;
  writeFileSync(eventsFile, JSON.stringify(state, null, 2));

  let safeMessage = message.startsWith('-') ? 'User says: ' + message : message;

  // Attempt RAG retrieval and prepend results to the message if available
  try {
    if (process.env.DISABLE_RAG !== '1') {
      const hits = await retrieve(message, 5);
      if (hits && hits.length) {
        const snippets = hits
          .map((h, i) => `Source ${i + 1} (${h.meta.path || h.id})\n${(h.text || '').slice(0, 800)}`)
          .join('\n\n---\n\n');
          const ragPrefix = `[RETRIEVED SOURCES]\n${snippets}\n[END RETRIEVED]\n\n`;
          safeMessage = ragPrefix + safeMessage;
      }
    }
  } catch (e) {
    // retrieval failed silently — continue without RAG
  }

  return streamClaude(
    {
      prompt: safeMessage,
      projectDir: MANUAL_DIR,
      model,
      resume: sessionId || undefined,
      systemPrompt: MANUAL_PROMPTS[agent] || MANUAL_PROMPTS.A,
      modelProvider,
    },
    eventsFile,
    agent,
    sessionId
  );
}

// ── Pipeline mode ───────────────────────────────────────────────────

async function handlePipeline(
  agent: string,
  message: string,
  model?: string,
  modelProvider?: string,
  defaults?: { securityMode?: SecurityMode; permissionMode?: PermissionMode; runGoal?: RunGoal; runFinalAudit?: boolean }
) {
  let projectDir: string;
  let eventsFile: string;

  const stagingEvents = join(STAGING_DIR, 'pipeline-events.json');
  const activeProject = findLatestProject();

  if (existsSync(stagingEvents)) {
    projectDir = STAGING_DIR;
    eventsFile = stagingEvents;
  } else if (activeProject) {
    const projState = JSON.parse(readFileSync(join(activeProject, 'pipeline-events.json'), 'utf8'));
    const phase = projState.currentPhase as string;
    const isActive = phase && phase !== 'concept' && !projState.buildComplete;
    const isDone = !!projState.buildComplete;
    if (isActive || isDone) {
      projectDir = activeProject;
      eventsFile = join(activeProject, 'pipeline-events.json');
    } else {
      projectDir = STAGING_DIR;
      eventsFile = stagingEvents;
      getStagingState();
    }
  } else {
    projectDir = STAGING_DIR;
    eventsFile = stagingEvents;
    getStagingState();
  }

  let state: Record<string, unknown> = {};
  try { state = JSON.parse(readFileSync(eventsFile, 'utf8')); } catch {}
  const securityMode = state.securityMode === 'strict' ? 'strict' : 'fast';
  const sessions = (state.sessions as Record<string, string>) || {};
  const sessionId = sessions[agent] || '';
  const effectiveModel = model || String(state.selectedModel || 'claude-opus-4-6');

  if (agent === 'S') {
    const intent = parseSupervisorIntent(message);
    if (intent) {
      let controlProjectDir = projectDir;
      let controlEventsFile = eventsFile;
      let controlState = state;

      if (intent.action === 'start-run') {
        controlProjectDir = STAGING_DIR;
        controlEventsFile = join(STAGING_DIR, 'pipeline-events.json');
        controlState = getStagingState();

        if (!controlState.concept && typeof intent.concept === 'string' && intent.concept.trim()) {
          controlState.concept = intent.concept.trim();
        }
      }

      appendUserEvent(controlState, agent, message);
      writeState(controlEventsFile, controlState);

      if (intent.action === 'start-run') {
        const effectiveSecurityMode = defaults?.securityMode || (controlState.securityMode === 'strict' ? 'strict' : 'fast');
        const effectiveRunGoal = defaults?.runGoal || 'full-build';
        const effectivePermissionMode = defaults?.permissionMode || 'auto';
        const effectiveRunFinalAudit = defaults?.runFinalAudit === true || controlState.runFinalAudit === true;
        const result = startPipelineRun({
          securityMode: effectiveSecurityMode,
          permissionMode: effectivePermissionMode as 'auto' | 'plan' | 'dangerously-skip-permissions',
          runGoal: effectiveRunGoal,
          runFinalAudit: effectiveRunFinalAudit,
        });

        if (!result.success) {
          appendSupervisorFailureAndGuidance(
            controlState,
            controlEventsFile,
            result.error || 'Supervisor could not start the run'
          );
          return NextResponse.json({ success: false, error: result.error || 'Could not start pipeline' });
        }

        appendPipelineEvent(result.projectDir!, {
          agent: 'S',
          phase: 'concept',
          type: 'status',
          text:
            result.runGoal === 'plan-only'
              ? `Supervisor started plan-only mode in ${result.securityMode} mode. A will plan, B will review, then the run will pause.`
              : `Supervisor started the full build in ${result.securityMode} mode.`,
        });

        return NextResponse.json({
          success: true,
          controlAction: 'start-run',
          projectDir: result.projectDir,
          runGoal: result.runGoal,
          securityMode: result.securityMode,
        });
      }

      if (intent.action === 'set-stop-after-review') {
        const result = setStopAfterReview(intent.enabled, controlProjectDir === STAGING_DIR ? undefined : controlProjectDir);
        if (!result.success) {
          appendSupervisorFailureAndGuidance(
            controlState,
            controlEventsFile,
            result.error || 'Supervisor could not update stop-after-review'
          );
          return NextResponse.json({ success: false, error: result.error || 'Could not update supervisor control' });
        }

        return NextResponse.json({
          success: true,
          controlAction: 'set-stop-after-review',
          stopAfterPhase: result.stopAfterPhase,
          projectDir: result.projectDir,
        });
      }

      if (intent.action === 'resume-run') {
        const result = resumePipelineRun(controlProjectDir === STAGING_DIR ? undefined : controlProjectDir);
        if (!result.success) {
          appendSupervisorFailureAndGuidance(
            controlState,
            controlEventsFile,
            result.error || 'Supervisor could not resume the run'
          );
          return NextResponse.json({ success: false, error: result.error || 'Could not resume pipeline' });
        }

        return NextResponse.json({
          success: true,
          controlAction: result.action || 'resume-run',
          projectDir: result.projectDir,
        });
      }

      if (intent.action === 'stop-run') {
        const result = stopPipelineRun(controlProjectDir === STAGING_DIR ? undefined : controlProjectDir);
        appendPipelineEvent(result.projectDir || controlProjectDir, {
          agent: 'S',
          phase: String(controlState.currentPhase || 'concept'),
          type: 'status',
          text: 'Supervisor stopped the run',
        });
        return NextResponse.json({ success: true, controlAction: 'stop-run', projectDir: result.projectDir });
      }
    }

    const isConceptPhase =
      projectDir === STAGING_DIR &&
      (!state.currentPhase || state.currentPhase === 'concept') &&
      !state.buildComplete;

    if (isConceptPhase) {
      // First message — no concept yet. Capture it with a canned reply.
      if (!state.concept) {
        state.concept = message.trim();
        appendUserEvent(state, agent, message);
        const reply = buildSupervisorConceptReply(String(state.concept), true);
        const events = (state.events as Array<Record<string, unknown>>) || [];
        events.push({
          time: new Date().toISOString(),
          agent: 'S',
          phase: state.currentPhase || 'concept',
          type: 'text',
          text: reply,
        });
        state.events = events;
        writeState(eventsFile, state);

        return NextResponse.json({
          success: true,
          conceptCaptured: true,
          concept: state.concept,
        });
      }

      // Concept exists — stream everything to Claude so S can think.
      appendUserEvent(state, agent, message);
      writeState(eventsFile, state);

      const conceptContext = [
        `[CONCEPT PHASE — no pipeline running yet]`,
        `Current concept: ${state.concept}`,
        '',
        'The user is exploring this idea with you before starting the team.',
        'Engage naturally — give your honest opinion, ask clarifying questions, suggest improvements.',
        'If the user refines or changes the concept, acknowledge it conversationally.',
        'When they seem ready, remind them they can say `start planning`, `start plan only`, or `start full build`.',
        '',
        message,
      ].join('\n');

      return streamClaude(
        {
          prompt: conceptContext,
          projectDir,
          pipelineDir: BUILDUI_DIR,
          model: effectiveModel,
          roleFile: ROLE_FILES.S,
          resume: sessionId || undefined,
          pipelineAgent: 'S',
          securityMode,
          modelProvider,
        },
        eventsFile,
        agent,
        sessionId
      );
    }
  }

  if (!state.concept && message) {
    state.concept = message;
    writeState(eventsFile, state);
  }

  const currentPhase = state.currentPhase as string;
  const isPhase0 = !currentPhase || currentPhase === 'concept';
  const roleFile = (agent === 'A' && isPhase0) ? ROLE_A_PHASE0 : (ROLE_FILES[agent] || ROLE_FILES.A);

  const safeMessage = message.startsWith('-') ? 'User says: ' + message : message;
  const buildComplete = !!state.buildComplete;
  let finalMessage = safeMessage;
  if (agent === 'S') {
    const pendingApproval = projectDir !== STAGING_DIR ? readPendingApproval(projectDir) : null;
    finalMessage = [
      buildSupervisorSnapshot(state, pendingApproval),
      '',
      'Use the live snapshot above as the source of truth for the team state.',
      'Answer as the supervisor/operator for the dev team.',
      'Lead with one concrete recommendation when the user asks what to do next.',
      '',
      safeMessage,
    ].join('\n');
  }
  if (buildComplete) {
    finalMessage = '[The build pipeline has completed. The user is chatting with you directly for post-build work — reviewing, fixing, or modifying the project.]\n\n' + finalMessage;
  }

  appendUserEvent(state, agent, message);
  writeState(eventsFile, state);

  // Attempt RAG retrieval and prepend context to the prompt for the agent
  try {
    if (process.env.DISABLE_RAG !== '1') {
      const hits = await retrieve(message, 5);
      if (hits && hits.length) {
        const snippets = hits
          .map((h, i) => `Source ${i + 1} (${h.meta.path || h.id})\n${(h.text || '').slice(0, 800)}`)
          .join('\n\n---\n\n');
        finalMessage = `[RETRIEVED SOURCES]\n${snippets}\n[END RETRIEVED]\n\n` + finalMessage;
      }
    }
  } catch (e) {
    // ignore retrieval errors and proceed
  }

  return streamClaude(
    {
      prompt: finalMessage,
      projectDir,
      pipelineDir: BUILDUI_DIR,
      model: effectiveModel,
      roleFile,
      resume: sessionId || undefined,
      pipelineAgent: agent as PipelineAgentId,
      securityMode,
      modelProvider,
    },
    eventsFile,
    agent,
    sessionId
  );
}

// ── Route handler ───────────────────────────────────────────────────

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { agent, message, mode, model, modelProvider, securityMode, permissionMode, runGoal, runFinalAudit } = body || {};

    const providerError = validateExecutableProvider(modelProvider);
    if (providerError) {
      return NextResponse.json({ success: false, error: providerError }, { status: 400 });
    }

    if (mode === 'manual') {
      return await handleManual(agent, message, model || 'claude-sonnet-4-6', modelProvider);
    }

    return await handlePipeline(agent, message, model, modelProvider, {
      securityMode: securityMode === 'strict' ? 'strict' : 'fast',
      permissionMode: permissionMode === 'plan' ? 'plan' : permissionMode === 'dangerously-skip-permissions' ? 'dangerously-skip-permissions' : 'auto',
      runGoal: runGoal === 'plan-only' ? 'plan-only' : 'full-build',
      runFinalAudit: runFinalAudit === true,
    });
  } catch (err) {
    // Ensure the API always returns JSON so the client can parse and surface
    // a meaningful error rather than crashing with an unexpected JSON parse
    // failure. Persist the error to a server-side log for debugging.
    try {
      appendServerLog(String(err instanceof Error ? err.stack || err.message : err), { route: 'api/chat' });
    } catch {}
    console.error('[api/chat] unexpected error:', err);
    return NextResponse.json({ success: false, error: String(err) }, { status: 500 });
  }
}

interface PipelineEvent {
  time: string;
  agent: 'A' | 'B' | 'C' | 'D' | 'E' | 'S' | 'system';
  phase: string;
  type: string;
  text: string;
  detail?: string;
}

interface TokenUsage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  totalCostUsd: number;
}

interface AuditFindingHistoryEntry {
  time: string;
  action: 'created' | 'sent-to-c' | 'fix-applied' | 'fix-failed-tests' | 're-audit-passed' | 're-audit-failed' | 'dismissed';
  note?: string;
}

interface AuditFinding {
  id: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  text: string;
  status: AuditFindingStatus;
  createdAt: string;
  history: AuditFindingHistoryEntry[];
}

interface PipelineState {
  concept: string;
  projectDir: string;
  currentPhase: string;
  securityMode: 'fast' | 'strict';
  runGoal: 'full-build' | 'plan-only';
  runFinalAudit: boolean;
  stopAfterPhase: 'none' | 'plan-review';
  pipelineStatus: 'idle' | 'running' | 'paused' | 'awaiting-audit-decision' | 'complete' | 'failed';
  resumeAction?: 'none' | 'continue-approved-plan' | 'resume-stalled-turn' | 'audit-send-to-c' | 'audit-dismiss' | 'audit-deploy';
  resumeActionTarget?: string;
  activeAgent: string;
  agentStatus: Record<string, string>;
  sessions: Record<string, string>;
  buildComplete: boolean;
  usage: TokenUsage;
  runtime: PipelineRuntimeState;
  events: PipelineEvent[];
  auditFindings?: AuditFinding[];
  auditDeployPending?: boolean;
  auditActionInFlight?: boolean;
}

function emit(
  agent: PipelineEvent['agent'],
  phase: string,
  type: string,
  text: string,
  detail?: string
) {
  state.events.push({ time: new Date().toISOString(), agent, phase, type, text, detail });
  flush();

  // Terminal output with color
  const time = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
  const colors: Record<string, string> = {
    status: '\x1b[36m', send: '\x1b[33m', receive: '\x1b[33m',
    question: '\x1b[35m', answer: '\x1b[32m', issue: '\x1b[31m',
    fix: '\x1b[32m', approval: '\x1b[1m\x1b[32m', failure: '\x1b[31m',
    tool_call: '\x1b[90m', tool_result: '\x1b[90m', text: '\x1b[37m',
  };
  const c = colors[type] || '\x1b[0m';
  console.log(`${c}[${time}]   ${agent} | ${text}\x1b[0m`);
}

function emitSupervisor(phase: string, text: string) {
  emit('S', phase, 'text', text);
}

function setAgent(agent: string, status: string) {
  state.agentStatus[agent] = status;
  if (status === 'active') state.activeAgent = agent;
  flush();
}

function setPhase(phase: string) {
  state.currentPhase = phase;
  flush();
}

function setPipelineStatus(status: PipelineState['pipelineStatus']) {
  state.pipelineStatus = status;
  flush();
}

function saveSession(agent: string, sessionId: string) {
  state.sessions[agent] = sessionId;
  if (state.runtime.activeTurn?.agent === agent) {
    state.runtime.activeTurn.sessionId = sessionId;
  }
  flush();
}

function startActiveTurn(agent: AgentId, prompt: string, autoResumeCount: number, resume?: string) {
  const now = new Date().toISOString();
  state.runtime.activeTurn = {
    agent,
    phase: state.currentPhase,
    status: 'running',
    startedAt: now,
    lastEventAt: now,
    sessionId: resume || state.sessions[agent] || '',
    promptSummary: summarizePrompt(prompt),
    autoResumeCount,
  };
  flush();
}

function noteActiveTurnActivity(agent: AgentId) {
  const activeTurn = state.runtime.activeTurn;
  if (!activeTurn || activeTurn.agent !== agent) return;

  activeTurn.lastEventAt = new Date().toISOString();
  if (activeTurn.status === 'stalled') {
    activeTurn.status = 'running';
    delete activeTurn.stalledAt;
    delete activeTurn.stallReason;
  }
  flush();
}

function markActiveTurnStalled(agent: AgentId, reason: string) {
  const activeTurn = state.runtime.activeTurn;
  if (!activeTurn || activeTurn.agent !== agent || activeTurn.status === 'stalled') return;

  activeTurn.status = 'stalled';
  activeTurn.stalledAt = new Date().toISOString();
  activeTurn.stallReason = reason;
  flush();
}

function clearActiveTurn(agent: AgentId) {
  if (state.runtime.activeTurn?.agent !== agent) return;
  state.runtime.activeTurn = null;
  flush();
}

function buildApprovalDescription(toolInput: Record<string, unknown>): string {
  const command = typeof toolInput.command === 'string' ? toolInput.command.trim() : '';
  if (command) return command;
  return JSON.stringify(toolInput);
}

function agentRoleLabel(agent: AgentId): string {
  switch (agent) {
    case 'A':
      return 'planner';
    case 'B':
      return 'plan reviewer';
    case 'C':
      return 'coder';
    case 'D':
      return 'tester';
    case 'E':
      return 'security auditor';
  }
}

async function runClaudeTurn(
  agent: AgentId,
  prompt: string,
  opts: {
    role: string;
    resume?: string;
    jsonSchema?: Record<string, unknown>;
    autoResumeCount?: number;
    forceHost?: boolean;
  }

function noteDiagnostic(text: string) {
  if (!text) return;
  diagnosticTail = `${diagnosticTail}\n${text}`.slice(-12_000);
}

async function claude(
  agent: AgentId,
  prompt: string,
  opts: {
    role: string;
    resume?: string;
    jsonSchema?: Record<string, unknown>;
    resumePrompt?: string;
    restartOnStall?: boolean;
  }

function parseSignal(result: string): Record<string, unknown> {
  // Try direct JSON parse
  try {
    return JSON.parse(result);
  } catch {
    // Try to find JSON embedded in text
    const match = result.match(/\{[\s\S]*"status"\s*:\s*"[^"]+"/);
    if (match) {
      try {
        let depth = 0;
        const start = result.indexOf(match[0]);
        for (let i = start; i < result.length; i++) {
          if (result[i] === '{') depth++;
          if (result[i] === '}') depth--;
          if (depth === 0) {
            return JSON.parse(result.slice(start, i + 1));
          }
        }
      } catch {}
    }
    // Try to detect positive/negative signals from text
    const lower = result.toLowerCase();
    if (lower.includes('all tests pass') || lower.includes('tests passed') || lower.includes('approved') || lower.includes('code is correct')) {
      emit('system', state.currentPhase, 'status', 'Parsed positive signal from text');
      return { status: 'approved' };
    }
    emit('system', state.currentPhase, 'status', 'Could not parse signal — treating as approved');
    return { status: 'approved' };
  }
}

// Normalize signal status — treat approved/passed as the same positive result
function isPositiveSignal(signal: Record<string, unknown>): boolean {
  const s = (signal.status as string || '').toLowerCase();
  return s === 'approved' || s === 'passed';
}

function buildPhase0Context() {
  const phase0Events = state.events.filter(
    (event) =>
      event.phase === 'concept' &&
      (
        event.type === 'user_msg' ||
        event.type === 'handoff' ||
        ((event.agent === 'A' || event.agent === 'S') && event.type === 'text')
      )
  );
  if (phase0Events.length === 0) return '';

  return 'Here is the Phase 0 concept conversation and supervisor context about what to build:\n\n' +
    phase0Events.map((event) => `${event.agent}: ${event.text}`).join('\n') + '\n\n';
}

async function runPlanningPhase(aSession: string, options?: { resumeStalled?: boolean }): Promise<string> {
  setPhase('planning');
  setPipelineStatus('running');
  setAgent('A', 'active');
  const phase0Context = buildPhase0Context();
  const existingPlanPath = join(projectDir, 'plan.md');
  let step = detectPlanningStep(state.events, { planExists: existsSync(existingPlanPath) });
  const resumeSession = aSession || state.runtime.activeTurn?.sessionId || state.sessions.A;

  if (options?.resumeStalled) {
    emit('system', 'planning', 'status', 'Supervisor resumed A from the saved planning session');
    emitSupervisor('planning', 'I resumed the planner from the saved session so we do not have to throw away the research and start over.');
  }

  if (step === 'research') {
    emit('A', 'planning', 'status', options?.resumeStalled ? 'Resuming research pass...' : 'Starting research pass...');
    if (options?.resumeStalled) {
      emitSupervisor('planning', 'The planner is finishing the research pass from the saved session.');
    }

    const researchResult = await claude('A', buildPlanningResearchPrompt(phase0Context, concept), {
      role: ROLE_A,
      resume: options?.resumeStalled ? resumeSession : undefined,
      resumePrompt: buildPlanningResearchResumePrompt(),
    });
    aSession = researchResult.sessionId;
    saveSession('A', aSession);

    step = detectPlanningStep(state.events, { planExists: existsSync(existingPlanPath) });
    if (step === 'research') step = 'write';
  }

  if (step === 'write') {
    const restartWriteFromSummary =
      options?.resumeStalled &&
      !existsSync(existingPlanPath) &&
      hasPlanningWriteStarted(state.events);
    const researchSummary = restartWriteFromSummary ? extractPlanningResearchSummary(state.events) : null;

    emit('A', 'planning', 'status', 'Writing plan.md...');
    emitSupervisor(
      'planning',
      restartWriteFromSummary
        ? 'The planner got stuck in the old write session, so I am restarting the write step from the verified research summary instead of looping the same resume again.'
        : 'Research is complete. The planner is drafting plan.md now in a dedicated write step so we do not lose the work between research and output.'
    );

    const writeResult = await claude('A', buildPlanningWritePrompt(projectDir, researchSummary), {
      role: ROLE_A,
      resume: restartWriteFromSummary ? undefined : (aSession || (options?.resumeStalled ? resumeSession : undefined)),
      resumePrompt: buildPlanningWriteResumePrompt(projectDir, researchSummary),
      restartOnStall: restartWriteFromSummary,
    });
    aSession = writeResult.sessionId;
    saveSession('A', aSession);

    if (!existsSync(existingPlanPath)) {
      emit('A', 'planning', 'failure', 'Did not write plan.md');
      throw new Error('Agent A did not write plan.md');
    }

    step = detectPlanningStep(state.events, { planExists: true });
    if (step !== 'done') step = 'self-review';
  }

  if (step === 'self-review') {
    emit('A', 'planning', 'status', 'Self-reviewing plan.md...');
    emitSupervisor(
      'planning',
      'The planner has a draft. It is doing one focused self-review pass before handing the plan to the reviewer.'
    );

    const reviewResult = await claude('A', buildPlanningSelfReviewPrompt(projectDir), {
      role: ROLE_A,
      resume: aSession || (options?.resumeStalled ? resumeSession : undefined),
      resumePrompt: buildPlanningSelfReviewResumePrompt(projectDir),
    });
    aSession = reviewResult.sessionId;
    saveSession('A', aSession);

    emit('A', 'planning', 'status', 'Plan self-review complete');
  }

  if (!existsSync(existingPlanPath)) {
    emit('A', 'planning', 'failure', 'Did not write plan.md');
    throw new Error('Agent A did not write plan.md');
  }

  emit('A', 'planning', 'status', 'Plan written to plan.md');
  return aSession;
}

async function runPlanReviewPhase(
  aSession: string,
  options?: {
    resumeStalledAgent?: 'A' | 'B';
    bSession?: string;
    emitInitialSend?: boolean;
  }
): Promise<{ aSession: string; bSession?: string; reviewRound: number; paused: boolean }> {
  let bSession = options?.bSession || state.sessions.B || undefined;
  let planApproved = false;
  let reviewRound = state.events.filter(
    (event) => event.agent === 'B' && event.phase === 'plan-review' && event.type === 'status' && /^Review round \d+/.test(event.text)
  ).length;

  setPhase('plan-review');
  setPipelineStatus('running');
  setAgent('A', 'idle');
  setAgent('B', 'active');

  if (options?.emitInitialSend !== false) {
    emit('A', 'plan-review', 'send', 'Sent plan to B for review');
    emitSupervisor('plan-review', 'The planner handed the plan to the reviewer. We are still before coding, so this is the right place to catch gaps.');
  }

  if (options?.resumeStalledAgent === 'A') {
    setAgent('B', 'idle');
    setAgent('A', 'active');
    emit('system', 'plan-review', 'status', 'Supervisor resumed A during plan review');
    emitSupervisor('plan-review', 'I resumed the planner during review so the plan can keep moving without resetting the whole run.');

    const aResume = await claude('A', buildResumePrompt('A', 'plan-review'), {
      role: ROLE_A,
      resume: aSession || state.runtime.activeTurn?.sessionId || state.sessions.A,
    });
    aSession = aResume.sessionId;
    saveSession('A', aSession);

    emit('A', 'plan-review', 'answer', 'Answered questions and updated plan');
    emit('A', 'plan-review', 'send', 'Sent updated plan to B');
    setAgent('A', 'idle');
    setAgent('B', 'active');
  }

  let nextBPrompt =
    options?.resumeStalledAgent === 'B'
      ? buildResumePrompt('B', 'plan-review')
      : options?.resumeStalledAgent === 'A'
      ? [
          'A has answered your questions and updated the plan.',
          `Review the updated plan at ${join(projectDir, 'plan.md')} again.`,
          'If you still have concerns, respond with status "questions" and list them.',
          'If the plan is now bulletproof, respond with status "approved".',
          '',
          'Respond with ONLY a JSON object: {"status": "approved"} or {"status": "questions", "questions": ["..."]}',
        ].join('\n')
      : [
          `Review the plan at ${join(projectDir, 'plan.md')}`,
          'Read the entire plan. Look for gaps, unverified assumptions, incomplete code, or anything the coder would need to guess at.',
          '',
          'Be concise. Do NOT summarize or repeat the plan back. Do NOT list what looks good.',
          'Just give your verdict: approved, or list the specific issues.',
          '',
          'Respond with ONLY a JSON object: {"status": "approved"} or {"status": "questions", "questions": ["..."]}',
        ].join('\n');
  let nextBResume = options?.resumeStalledAgent === 'B'
    ? (state.runtime.activeTurn?.sessionId || bSession)
    : bSession;

  while (!planApproved) {
    reviewRound += 1;
    emit('B', 'plan-review', 'status', `Review round ${reviewRound}...`);

    const bResult = await claude('B', nextBPrompt, {
      role: ROLE_B,
      resume: nextBResume,
      jsonSchema: REVIEW_SCHEMA,
    });
    bSession = bResult.sessionId;
    saveSession('B', bSession);

    const signal = bResult.structured || parseSignal(bResult.result);

    if (isPositiveSignal(signal)) {
      planApproved = true;
      emit('B', 'plan-review', 'approval', 'PLAN APPROVED');
      emitSupervisor('plan-review', 'The reviewer approved the plan. The build doctrine is locked now, so coding can start from a stable contract.');
      setAgent('B', 'done');
      break;
    }

    const questions = (signal.questions as string[]) || [];
    questions.forEach((question, index) => {
      emit('B', 'plan-review', 'question', `Q${index + 1}: ${question}`);
    });

    emit('B', 'plan-review', 'send', `Sent ${questions.length} question(s) to A`);

    setAgent('A', 'active');
    emit('A', 'plan-review', 'receive', `Received ${questions.length} question(s) from B`);

    const aFollowup = await claude('A', [
      'Agent B (Plan Reviewer) has questions about your plan:',
      '',
      ...questions.map((question, index) => `${index + 1}. ${question}`),
      '',
      'Answer each question with verified information.',
      `Update ${join(projectDir, 'plan.md')} with any corrections or additions.`,
      'Do not guess. Verify from source.',
    ].join('\n'), { role: ROLE_A, resume: aSession });
    aSession = aFollowup.sessionId;
    saveSession('A', aSession);

    emit('A', 'plan-review', 'answer', 'Answered questions and updated plan');
    emit('A', 'plan-review', 'send', 'Sent updated plan to B');
    setAgent('A', 'idle');
    setAgent('B', 'active');

    nextBPrompt = [
      'A has answered your questions and updated the plan.',
      `Review the updated plan at ${join(projectDir, 'plan.md')} again.`,
      'If you still have concerns, respond with status "questions" and list them.',
      'If the plan is now bulletproof, respond with status "approved".',
      '',
      'Respond with ONLY a JSON object: {"status": "approved"} or {"status": "questions", "questions": ["..."]}',
    ].join('\n');
    nextBResume = bSession;
  }

  emit('A', 'plan-review', 'status', 'Plan locked — final, unmodifiable copy');

  if (shouldStopAfterPlanReview()) {
    state.activeAgent = '';
    setPipelineStatus('paused');
    emitSupervisor(
      'plan-review',
      state.runGoal === 'plan-only'
        ? 'Planning is complete and I paused the team before coding, exactly as requested.'
        : 'I paused the team after approved plan review, so you can decide whether to continue into coding.'
    );
    emit(
      'system',
      'plan-review',
      'status',
      state.runGoal === 'plan-only'
        ? 'Plan-only run complete. Supervisor stopped after approved plan review.'
        : 'Supervisor stopped the pipeline after approved plan review.'
    );
    flush();
    return { aSession, bSession, reviewRound, paused: true };
  }

  return { aSession, bSession, reviewRound, paused: false };
}

async function runSecurityAudit(): Promise<{ paused: boolean }> {
  if (!state.runFinalAudit) return { paused: false };

  setPhase('security-audit');
  setPipelineStatus('running');
  setAgent('E', 'active');
  emit('D', 'security-audit', 'send', 'Sent reviewed and tested code to E for security audit');
  emit('E', 'security-audit', 'receive', 'Received reviewed and tested code from D');
  emit('E', 'security-audit', 'status', 'Auditing for OWASP Top 10, path traversal, ReDoS, missing input validation...');
  emitSupervisor(
    'security-audit',
    'Tests passed. The security auditor is doing a final static pass before we hand the build back to you for review.'
  );

  const auditPrompt = [
    `Read the locked plan at ${join(projectDir, 'plan.md')}.`,
    `Then enumerate and read every code file in ${projectDir} that C produced.`,
    'Audit statically for the OWASP Top 10, path traversal, ReDoS, and missing input validation on public boundaries.',
    'Only flag real, exploitable vulnerabilities you can point to with a file and line.',
    'Rank each finding by severity: critical / high / medium / low. Calibrate by exploitability and prerequisites, not by general code quality.',
    '',
    'Respond with ONLY a JSON object: {"status": "approved"} or {"status": "issues", "issues": [{"severity": "...", "finding": "[file/line] type: description and fix"}]}',
  ].join('\n');

  const auditResult = await claude('E', auditPrompt, {
    role: ROLE_E,
    jsonSchema: AUDIT_SCHEMA,
  });
  saveSession('E', auditResult.sessionId);

  const signal = auditResult.structured || parseSignal(auditResult.result);
  const findings: AuditFinding[] = [];

  if (!isPositiveSignal(signal)) {
    const rawIssues = Array.isArray(signal.issues) ? signal.issues : [];
    const validSeverities: AuditFinding['severity'][] = ['critical', 'high', 'medium', 'low'];
    const nowIso = new Date().toISOString();
    for (const raw of rawIssues) {
      let severity: AuditFinding['severity'] = 'medium';
      let text = '';
      if (typeof raw === 'string') {
        // Defensive: legacy bare-string shape. Default severity to medium.
        text = raw;
      } else if (raw && typeof raw === 'object') {
        const obj = raw as { severity?: unknown; finding?: unknown };
        if (typeof obj.severity === 'string' && validSeverities.includes(obj.severity as AuditFinding['severity'])) {
          severity = obj.severity as AuditFinding['severity'];
        }
        if (typeof obj.finding === 'string') {
          text = obj.finding;
        }
      }
      if (!text) continue;
      findings.push({
        id: `finding-${randomUUID().slice(0, 8)}`,
        severity,
        text,
        status: 'open',
        createdAt: nowIso,
        history: [{ time: nowIso, action: 'created' }],
      });
    }
  }

  state.auditFindings = findings;
  state.auditDeployPending = true;
  setPipelineStatus('awaiting-audit-decision');
  setAgent('E', 'done');

  if (findings.length === 0) {
    emit('E', 'security-audit', 'approval', 'AUDIT CLEAN — no findings');
    emitSupervisor(
      'security-audit',
      'Audit is clean — no exploitable vulnerabilities found. Click Deploy in the Security Audit panel when you are ready to finish the build.'
    );
  } else {
    findings.forEach((f) => {
      emit('E', 'security-audit', 'issue', `[${f.severity}] ${f.text}`);
    });
    const counts = findings.reduce((acc, f) => {
      acc[f.severity] = (acc[f.severity] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);
    const summaryParts = (['critical', 'high', 'medium', 'low'] as const)
      .filter((s) => counts[s])
      .map((s) => `${counts[s]} ${s}`);
    emitSupervisor(
      'security-audit',
      `Audit found ${findings.length} finding${findings.length === 1 ? '' : 's'} (${summaryParts.join(', ')}). Waiting on your review — decide per finding in the Security Audit panel, then click Deploy.`
    );
  }

  flush();
  return { paused: true };
}

async function runDeployStep(aSession: string): Promise<string> {
  setPhase('deploy');
  setAgent('A', 'active');
  emit('D', 'deploy', 'send', 'Sent reviewed + tested code to A');
  emit('A', 'deploy', 'receive', 'Received final code from D');
  emit('A', 'deploy', 'status', 'Deploying...');

  const aDeployResult = await claude('A', [
    'The code has been reviewed and tested by Agent D. Everything passed.',
    'Do not use Bash or git. The orchestrator will handle any final commit.',
    'Confirm the build is complete and mention any environment caveats the user should know.',
  ].join('\n'), { role: ROLE_A, resume: aSession });
  aSession = aDeployResult.sessionId;
  saveSession('A', aSession);

  setAgent('A', 'done');
  setPhase('complete');
  setPipelineStatus('complete');
  state.buildComplete = true;
  emit('A', 'deploy', 'approval', 'BUILD COMPLETE');
  emitSupervisor('complete', 'The team finished the build. You can inspect the output now or jump into any specialist chat for follow-up work.');

  try {
    execFileSync('git', ['add', '.'], { cwd: projectDir });
    execFileSync('git', ['commit', '-m', `Build complete: ${concept.slice(0, 50)}`], { cwd: projectDir });
    emit('system', 'complete', 'status', 'Code committed to git');
  } catch {}

  try {
    const files = readdirSync(projectDir);
    const htmlFile = files.find((file) => file === 'index.html') || files.find((file) => file.endsWith('.html'));
    if (htmlFile) {
      execFileSync('open', [join(projectDir, htmlFile)]);
      emit('system', 'complete', 'status', `Opened ${htmlFile}`);
    }
  } catch {}

  return aSession;
}

// ── Audit action handlers (user-initiated fix/dismiss/deploy after audit pause) ──

async function runAuditFixPass(findingId: string): Promise<void> {
  const findings = state.auditFindings || [];
  const finding = findings.find((f) => f.id === findingId);
  if (!finding) {
    emit('system', 'security-audit', 'issue', `Requested fix for unknown finding ${findingId} — ignored.`);
    return;
  }
  if (finding.status === 'resolved' || finding.status === 'dismissed') {
    emit('system', 'security-audit', 'status', `Finding ${findingId} already ${finding.status} — skipping fix.`);
    return;
  }

  const nowIso = () => new Date().toISOString();

  finding.status = 'sent-to-c';
  finding.history.push({ time: nowIso(), action: 'sent-to-c' });
  setPhase('security-audit');
  setAgent('C', 'active');
  emit('E', 'security-audit', 'send', `Finding ${finding.id} sent to C for a scoped fix: ${finding.text}`);
  emitSupervisor('security-audit', `C is applying a scoped fix for finding ${finding.id} (${finding.severity}).`);
  flush();

  const cSession = state.sessions?.C;
  const cPrompt = [
    'Agent E flagged a security finding that the user asked you to fix.',
    'Fix ONLY this finding. Do not touch anything else. Do not modify plan.md.',
    'The rest of the codebase has passed review and testing — keep it that way.',
    '',
    `Finding: ${finding.text}`,
    '',
    'When you are done, confirm what you changed in one sentence.',
  ].join('\n');
  const cResult = await claude('C', cPrompt, { role: ROLE_C, resume: cSession });
  saveSession('C', cResult.sessionId);
  finding.history.push({ time: nowIso(), action: 'fix-applied' });
  emit('C', 'security-audit', 'fix', `Applied scoped fix for ${finding.id}`);
  setAgent('C', 'done');
  flush();

  setAgent('D', 'active');
  const dSession = state.sessions?.D;
  const dPrompt = [
    `Agent C applied a scoped security fix for this finding: "${finding.text}"`,
    'Run the existing tests. Confirm nothing regressed.',
    '',
    'Respond with ONLY: {"status": "passed"} or {"status": "failed", "failures": ["..."]}',
  ].join('\n');
  const dResult = await claude('D', dPrompt, { role: ROLE_D, resume: dSession, jsonSchema: TEST_SCHEMA });
  saveSession('D', dResult.sessionId);
  const dSignal = dResult.structured || parseSignal(dResult.result);
  setAgent('D', 'done');

  if (!isPositiveSignal(dSignal)) {
    const failures = Array.isArray(dSignal.failures) ? (dSignal.failures as string[]) : [];
    const failureNote = failures.length ? failures.join(' | ') : 'Tests failed without structured failure details.';
    finding.status = 'open';
    finding.history.push({ time: nowIso(), action: 'fix-failed-tests', note: failureNote });
    emit('D', 'security-audit', 'failure', `Fix for ${finding.id} broke tests: ${failureNote}`);
    emitSupervisor('security-audit', `C's fix for ${finding.id} broke tests. The finding is back to Open — decide whether to retry, dismiss, or ignore.`);
    flush();
    return;
  }

  finding.status = 're-auditing';
  setAgent('E', 'active');
  emit('D', 'security-audit', 'send', `Fix for ${finding.id} passed tests. Sending to E for re-audit.`);
  flush();

  const eSession = state.sessions?.E;
  const ePrompt = [
    'Re-audit ONLY this finding after a scoped fix was applied.',
    `Original finding: ${finding.text}`,
    'Read only the file(s) this finding referenced. Confirm whether the vulnerability is closed.',
    '',
    'Respond with ONLY the same JSON schema: {"status": "approved"} or {"status": "issues", "issues": [{"severity": "...", "finding": "[file/line] type: description and fix"}]}',
  ].join('\n');
  const eResult = await claude('E', ePrompt, { role: ROLE_E, resume: eSession, jsonSchema: AUDIT_SCHEMA });
  saveSession('E', eResult.sessionId);
  const eSignal = eResult.structured || parseSignal(eResult.result);
  setAgent('E', 'done');

  if (isPositiveSignal(eSignal)) {
    finding.status = 'resolved';
    finding.history.push({ time: nowIso(), action: 're-audit-passed' });
    emit('E', 'security-audit', 'approval', `Finding ${finding.id} resolved ✓`);
    emitSupervisor('security-audit', `Finding ${finding.id} is resolved. Back to your review.`);
  } else {
    const rawIssues = Array.isArray(eSignal.issues) ? eSignal.issues : [];
    const firstIssue = rawIssues[0];
    let newText = finding.text;
    if (firstIssue) {
      if (typeof firstIssue === 'string') {
        newText = firstIssue;
      } else if (typeof firstIssue === 'object' && typeof (firstIssue as { finding?: unknown }).finding === 'string') {
        newText = (firstIssue as { finding: string }).finding;
      }
    }
    finding.status = 'still-open';
    finding.text = newText;
    finding.history.push({ time: nowIso(), action: 're-audit-failed', note: newText });
    emit('E', 'security-audit', 'issue', `Finding ${finding.id} still open: ${newText}`);
    emitSupervisor('security-audit', `Finding ${finding.id} is still open after C's fix. Decide whether to retry, dismiss, or ignore.`);
  }
  flush();
}

function dismissAuditFinding(findingId: string): void {
  const finding = (state.auditFindings || []).find((f) => f.id === findingId);
  if (!finding) {
    emit('system', 'security-audit', 'issue', `Requested dismiss for unknown finding ${findingId} — ignored.`);
    return;
  }
  finding.status = 'dismissed';
  finding.history.push({ time: new Date().toISOString(), action: 'dismissed' });
  emit('system', 'security-audit', 'dismissal', `User dismissed finding ${finding.id} (${finding.severity}): ${finding.text}`);
  emitSupervisor('security-audit', `Finding ${finding.id} dismissed.`);
  flush();
}

async function runAuditDeploy(): Promise<void> {
  state.auditDeployPending = false;
  setPipelineStatus('running');
  const findings = state.auditFindings || [];
  const resolved = findings.filter((f) => f.status === 'resolved').length;
  const dismissed = findings.filter((f) => f.status === 'dismissed').length;
  const stillOpen = findings.filter((f) =>
    f.status === 'open' ||
    f.status === 'still-open' ||
    f.status === 'sent-to-c' ||
    f.status === 're-auditing'
  ).length;
  emitSupervisor(
    'security-audit',
    `Deploying. Findings: ${resolved} resolved, ${dismissed} dismissed, ${stillOpen} still open.`
  );

  const aSession = state.sessions?.A || '';
  await runDeployStep(aSession);
}

async function handleAuditAction(): Promise<void> {
  const action = state.resumeAction;
  const targetId = state.resumeActionTarget;

  try {
    switch (action) {
      case 'audit-send-to-c':
        if (targetId) await runAuditFixPass(targetId);
        break;
      case 'audit-dismiss':
        if (targetId) dismissAuditFinding(targetId);
        break;
      case 'audit-deploy':
        await runAuditDeploy();
        break;
    }
  } finally {
    state.resumeAction = 'none';
    state.resumeActionTarget = undefined;
    state.auditActionInFlight = false;
    flush();
  }
}

async function runBuildFromCoding(aSession: string): Promise<{ aSession: string; codeReviewRound: number; testRound: number }> {
  setPhase('coding');
  setPipelineStatus('running');
  setAgent('C', 'active');
  emit('A', 'coding', 'send', 'Sent approved plan to C');
  emit('C', 'coding', 'receive', 'Received approved plan from A');
  emit('C', 'coding', 'status', 'Building...');
  emitSupervisor('coding', 'The coder is implementing the approved plan now. At this point the goal is execution, not re-deciding the design.');

  const cResult = await claude('C', [
    `Read the approved plan at ${join(projectDir, 'plan.md')}`,
    'Build exactly what it says. Every file, every modification, every special case.',
    'Do not improvise. Do not interpret. Do not "improve."',
    'Do not modify plan.md — it is locked.',
    'Do NOT use the Agent tool. Do NOT spawn sub-agents. Build everything yourself.',
    '',
    'When you are done, confirm what you built.',
  ].join('\n'), { role: ROLE_C });
  let cSession = cResult.sessionId;
  saveSession('C', cSession);

  emit('C', 'coding', 'status', 'Finished coding');

  setPhase('code-review');
  setAgent('C', 'idle');
  setAgent('D', 'active');
  emit('C', 'code-review', 'send', 'Sent code to D for review');
  emit('D', 'code-review', 'receive', 'Received code from C');
  emitSupervisor('code-review', 'The tester is reviewing the coder output against the approved plan before we trust the build.');

  let dSession: string | undefined;
  let codeApproved = false;
  let codeReviewRound = 0;

  while (!codeApproved) {
    codeReviewRound += 1;

    const dPrompt = dSession
      ? [
          'C has applied fixes to the code.',
          `Review the code again against the plan at ${join(projectDir, 'plan.md')}`,
          'Respond with ONLY a JSON object: {"status": "approved"} or {"status": "issues", "issues": ["..."]}',
        ].join('\n')
      : [
          `Read the plan at ${join(projectDir, 'plan.md')}`,
          'Read the code that C wrote.',
          'Check: does the code match the plan? Every item accounted for?',
          '',
          'Respond with ONLY a JSON object: {"status": "approved"} or {"status": "issues", "issues": ["..."]}',
        ].join('\n');

    emit('D', 'code-review', 'status', `Code review round ${codeReviewRound}...`);

    const dResult = await claude('D', dPrompt, {
      role: ROLE_D,
      resume: dSession,
      jsonSchema: CODE_REVIEW_SCHEMA,
    });
    dSession = dResult.sessionId;
    saveSession('D', dSession);

    const signal = dResult.structured || parseSignal(dResult.result);

    if (isPositiveSignal(signal)) {
      codeApproved = true;
      emit('D', 'code-review', 'approval', 'CODE APPROVED');
    } else {
      const issues = (signal.issues as string[]) || [];

      issues.forEach((issue, index) => {
        emit('D', 'code-review', 'issue', `Issue ${index + 1}: ${issue}`);
      });

      emit('D', 'code-review', 'send', `Sent ${issues.length} issue(s) to C`);
      setAgent('C', 'active');
      emit('C', 'code-review', 'receive', `Received ${issues.length} issue(s) from D`);

      const cReviewFollowup = await claude('C', [
        'Agent D (Code Reviewer) found issues with your code:',
        '',
        ...issues.map((issue, index) => `${index + 1}. ${issue}`),
        '',
        'Fix each issue. Do not modify plan.md.',
      ].join('\n'), { role: ROLE_C, resume: cSession });
      cSession = cReviewFollowup.sessionId;
      saveSession('C', cSession);

      emit('C', 'code-review', 'fix', 'Applied fixes');
      emit('C', 'code-review', 'send', 'Sent fixed code to D');
      setAgent('C', 'idle');
    }
  }

  setPhase('testing');
  emit('D', 'testing', 'status', 'Moving to testing...');
  emitSupervisor('testing', 'Code review is done. The tester is now running the build and checking whether it actually behaves the way the plan says it should.');

  let testsPassed = false;
  let testRound = 0;

  while (!testsPassed) {
    testRound += 1;

    const testPrompt = testRound === 1
      ? [
          'Code review is complete. Now test the code.',
          'Run it. Confirm it actually works — not just that it looks right.',
          `Test all functionality against the plan at ${join(projectDir, 'plan.md')}`,
          '',
          'Respond with ONLY a JSON object: {"status": "passed"} or {"status": "failed", "failures": ["..."]}',
        ].join('\n')
      : [
          'C has applied fixes for the test failures.',
          'Re-test the code.',
          'Respond with ONLY a JSON object: {"status": "passed"} or {"status": "failed", "failures": ["..."]}',
        ].join('\n');

    emit('D', 'testing', 'status', `Test round ${testRound}...`);

    const testResult = await claude('D', testPrompt, {
      role: ROLE_D,
      resume: dSession!,
      jsonSchema: TEST_SCHEMA,
    });
    dSession = testResult.sessionId;
    saveSession('D', dSession);

    const signal = testResult.structured || parseSignal(testResult.result);

    if (isPositiveSignal(signal)) {
      testsPassed = true;
      emit('D', 'testing', 'approval', 'ALL TESTS PASSED');
      setAgent('D', 'done');
    } else {
      const failures = (signal.failures as string[]) || [];

      failures.forEach((failure, index) => {
        emit('D', 'testing', 'failure', `Failure ${index + 1}: ${failure}`);
      });

      emit('D', 'testing', 'send', `Sent ${failures.length} failure(s) to C`);
      setAgent('C', 'active');
      emit('C', 'testing', 'receive', `Received ${failures.length} failure(s) from D`);

      const cTestFollowup = await claude('C', [
        'Agent D (Tester) found test failures:',
        '',
        ...failures.map((failure, index) => `${index + 1}. ${failure}`),
        '',
        'Fix each failure. Do not modify plan.md.',
      ].join('\n'), { role: ROLE_C, resume: cSession });
      cSession = cTestFollowup.sessionId;
      saveSession('C', cSession);

      emit('C', 'testing', 'fix', 'Applied fixes');
      emit('C', 'testing', 'send', 'Sent fixed code to D');
      setAgent('C', 'done');
    }
  }

  const auditOutcome = await runSecurityAudit();
  if (auditOutcome.paused) {
    // Orchestrator exits here. User actions drive the rest via /api/audit-action
    // which spawns a fresh orchestrator that routes through handleAuditAction().
    return { aSession, codeReviewRound, testRound };
  }

  aSession = await runDeployStep(aSession);

  return { aSession, codeReviewRound, testRound };
}

