function roleLabel(agent: string): string {
  switch (agent) {
    case 'A':
      return 'planner';
    case 'B':
      return 'plan reviewer';
    case 'C':
      return 'coder';
    case 'D':
      return 'tester';
    case 'E':
      return 'security auditor';
    case 'S':
    default:
      return 'supervisor';
  }
}

